import { useQuery, type UseQueryOptions } from "@tanstack/react-query";
import { listInboxHandler } from "../handlers/listInboxHandler";
import type { ApiError } from "../runtime/client";
import type { SpacePartition } from "../types/SpacePartition";

type Data = Awaited<ReturnType<typeof listInboxHandler>>;

export function useListInbox(
  unreadOnly?: boolean | null,
  spaceId?: SpacePartition | null,
  bookmark?: string | null,
  options?: Omit<UseQueryOptions<Data, ApiError>, "queryKey" | "queryFn">,
) {
  return useQuery<Data, ApiError>({
    queryKey: ["listInbox", unreadOnly, spaceId, bookmark],
    queryFn: () => listInboxHandler(unreadOnly, spaceId, bookmark),
    ...options,
  });
}
